def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    if color and platform.system() in ("Linux", "Darwin"):
        master, slave = pty.openpty()
    else:
        master = -1
    proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kwargs)
    if master != -1:
        os.close(master)
    stdin = os.fdopen(slave, "wb", 0)
    stdout = os.fdopen(slave, "rb", 0)
    stderr = os.fdopen(slave, "rb", 0)
    for arg in varargs:
        stdin.write(arg.encode() + b"\n")
    stdin.close()
    out, err = proc.communicate()
    return proc.returncode, out + err

