def cached(cache, key=hashkey, lock=None):
    def wrapper(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            key = key(*args, **kwargs)
            if key not in cache:
                cache[key] = func(*args, **kwargs)
            return cache[key]
        return wrapped
    return wrapper

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = {}
        def wrapped(*args):
            key = (args, frozenset(kwargs.items()))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
            elif timer() - cache[key][1] > ttl:
                del cache[key]
                cache[key] = func(*args, **kwargs)
            return cache[key][0]
        return wrapped
    return wrapper

def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
            elif cache[key] is None:
                return None
            else:
                del cache[key]
                cache[key] = func(*args, **kwargs)
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return cache[key]
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        def wrapped(*args):
            key = str(args) if typed else args
            if key not in cache:
                cache[key] = func(*args)
            return cache[key]
        return wrapped
    return wrapper

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        freq = defaultdict(set)
        hits = defaultdict(int)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                freq[key].add(len(cache))
            else:
                hits[key] += 1
                freq[key].remove(len(cache))
                freq[key].add(len(cache))
            if len(cache) > maxsize:
                # least frequently used
                for key, _ in freq.items():
                    if len(freq[key]) == 1:
                        break
                del cache[key]
                del freq[key]
            return cache[key]
        return wrapper
    return decorator

