def normalize_args(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if isinstance(sequence, Declaration):
        return sequence
    elif isinstance(sequence, tuple):
        return tuple(normalize_args(s) for s in sequence)
    elif isinstance(sequence, Interface):
        return sequence
    else:
        raise ValueError("Unsupported type for normalization: " + str(type(sequence)))

