def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value, first_level=first_level)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item, first_level=first_level) for item in value]
        else:
            observer_schema[key] = None
    if first_level:
        observer_schema["apiVersion"] = manifest_dict["apiVersion"]
        observer_schema["kind"] = manifest_dict["kind"]
    return observer_schema

