    for field in observer_schema:
        if field not in response:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        elif isinstance(last_applied_manifest[field], dict) and isinstance(response[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        elif isinstance(last_applied_manifest[field], list) and isinstance(response[field], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        else:
            last_applied_manifest[field] = response[field]

def format(sql, params):
    if isinstance(params, dict):
        params = {k: v for k, v in params.items()}
    elif isinstance(params, list):
        params = {i: v for i, v in enumerate(params)}
    else:
        raise ValueError("Invalid parameter type")

    if isinstance(sql, str):
        sql = sql.encode("utf-8")

    for key, value in params.items():
        if isinstance(key, str):
            sql = sql.replace(f"@{key}", f"@{value}")
        else:
            sql = sql.replace(f"@{key + 1}", f"@{value}")

    return sql, params

