def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check if the fixity block is present
    if not fixity:
        return

    # Check if the fixity block is a list
    if not isinstance(fixity, list):
        raise ValueError("Fixity block must be a list")

    # Check if all elements in the fixity block are dictionaries
    if not all(isinstance(element, dict) for element in fixity):
        raise ValueError("Fixity block must contain dictionaries")

    # Check if all required keys are present in the fixity block
    required_keys = ["file", "algorithm", "digest"]
    for element in fixity:
        for key in required_keys:
            if key not in element:
                raise ValueError(f"Fixity block must contain key '{key}'")

    # Check if all files listed in the fixity block are present in the manifest
    for element in fixity:
        file = element["file"]
        if file not in manifest_files:
            raise ValueError(f"File '{file}' listed in fixity block is not present in the manifest")

    # Check if all algorithms listed in the fixity block are supported
    supported_algorithms = ["md5", "sha1", "sha256", "sha512"]
    for element in fixity:
        algorithm = element["algorithm"]
        if algorithm not in supported_algorithms:
            raise ValueError(f"Algorithm '{algorithm}' listed in fixity block is not supported")

    # Check if all digests listed in the fixity block are valid
    for element in fixity:
        digest = element["digest"]
        if not re.match(r"^[a-f0-9]{32}$", digest):
            raise ValueError(f"Digest '{digest}' listed in fixity block is not valid")

