        # Get the inventory for the current version
        inventory = self.get_inventory(version_dir)

        # Check that the inventory exists
        if not inventory:
            raise ValueError(f"Inventory for version {version_dir} does not exist")

        # Check that the inventory is up to date
        if inventory["version"] != version_dir:
            raise ValueError(f"Inventory for version {version_dir} is not up to date")

        # Check that the content digests are the same as those in the root inventory
        for content_digest in inventory["content_digests"]:
            if content_digest not in version_digests:
                version_digests[content_digest] = version_dir
            elif version_digests[content_digest] != version_dir:
                raise ValueError(f"Content digest {content_digest} is different in version {version_dir} and {version_digests[content_digest]}")

