def isoparse(dt_str):
    # Initialize variables
    date_str = ""
    time_str = ""
    tz_str = ""
    date_parts = []
    time_parts = []
    tz_parts = []

    # Check if the input string is a valid ISO-8601 datetime string
    if not dt_str.isascii():
        raise ValueError("Invalid input string")

    # Split the input string into date, time, and time zone parts
    for part in dt_str.split("T"):
        if part.isdigit():
            date_parts.append(part)
        elif part.isalpha():
            time_parts.append(part)
        else:
            tz_parts.append(part)

    # Check if the date and time parts are valid
    if len(date_parts) > 3 or len(time_parts) > 3:
        raise ValueError("Invalid date or time format")

    # Check if the time zone part is valid
    if len(tz_parts) > 1:
        raise ValueError("Invalid time zone format")

    # Parse the date and time parts
    date = datetime.date(*date_parts)
    time = datetime.time(*time_parts)

    # Parse the time zone part
    if tz_parts:
        tz = tz_parts[0]
        if tz == "Z":
            tz = datetime.timezone.utc
        else:
            tz = datetime.timezone(datetime.timedelta(hours=int(tz[:3]), minutes=int(tz[3:])))

    # Return the datetime object
    return datetime.datetime.combine(date, time, tz)

