    except json.JSONDecodeError:
        pass

    # If the document is not JSON, try to parse it as XRD
    xrd = xrd11.parse_xrd(document)

    # Convert the XRD to a dictionary
    result = {}
    for link in xrd.links:
        result[link.rel] = link.href

    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    try:
        response = requests.get(f"https://webfinger.net/{handle}/.well-known/webfinger")
        if response.status_code == 200:
            return response.text
    except requests.exceptions.RequestException:
        return None

def retrieve_diaspora_host_meta(host):
    url = f"https://{host}/host-meta.xrds"
    response = requests.get(url)
    if response.status_code == 200:
        xrd = XRD.from_xml(response.content)
        return xrd
    else:
        raise ValueError(f"Failed to retrieve host-meta document from {host}")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    try:
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return response.status_code, None
    except Exception as e:
        return None, e

def dict_insert(dic, val, key, *keys):
    current = dic
    for k in keys:
        if k not in current:
            current[k] = {}
        current = current[k]
    current[key] = val

def list_of_file_names(settings_dirs, spec_option):
    file_names = []
    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
            for file in files:
                if file.endswith(spec_option):
                    file_names.append(os.path.join(root, file))
    return file_names

def validate_from_content(spec_content):
    if not spec_content:
        raise IRValidatorException("Mandatory data is missing in spec file")
    return yaml.safe_load(spec_content)

def validate_from_file(yaml_file):
    with open(yaml_file, "r") as f:
        data = yaml.safe_load(f)

    if not data.get("mandatory_field_1"):
        raise IRValidatorException("Mandatory field 'mandatory_field_1' is missing in file")

    if not data.get("mandatory_field_2"):
        raise IRValidatorException("Mandatory field 'mandatory_field_2' is missing in file")

    return data

def get_spec_defaults(self):
    spec_defaults = {}
    for arg in self.spec.args:
        if arg.default is not None:
            spec_defaults[arg.name] = arg.default
        elif arg.annotation is not None:
            spec_defaults[arg.name] = arg.annotation
    return spec_defaults

def get_deprecated_args(self):
    return {
        "option1": ["option2", "option3"],
        "option4": ["option5", "option6"],
        "option7": ["option8", "option9"]
    }

def validate_arg_deprecation(cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """

    # Check if any of the arguments in cli_args are deprecated
    for arg in cli_args:
        if arg in DEPRECATED_ARGS:
            print(f"Warning: The argument {arg} is deprecated and will be removed in a future version. Please use {DEPRECATED_ARGS[arg]} instead.")

    # Check if any of the arguments in answer_file_args are deprecated
    for arg in answer_file_args:
        if arg in DEPRECATED_ARGS:
            print(f"Warning: The argument {arg} is deprecated and will be removed in a future version. Please use {DEPRECATED_ARGS[arg]} instead.")

    # If any of the arguments are deprecated, raise a ValueError
    if any(arg in DEPRECATED_ARGS for arg in cli_args) or any(arg in DEPRECATED_ARGS for arg in answer_file_args):
        raise ValueError("The arguments provided are deprecated and cannot be used.")

def get_silent_args(self, args):
    silent_args = []
    for arg in args:
        if arg.startswith("-"):
            silent_args.append(arg)
    return silent_args

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    for arg in args:
        if arg.required and not arg.value:
            raise ValueError(f"Required argument {arg.name} is missing.")

def get_conditionally_required_args(command_name, options_spec, args):
    required_args = []
    for arg in args:
        if arg in options_spec and "required_when" in options_spec[arg]:
            required_when = options_spec[arg]["required_when"]
            if required_when in args:
                required_args.append(arg)
    return required_args

def validate_length_args(self, args):
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Value of argument {arg} is longer than {self.length}")

def validate_choices_args(self, args):
    for arg in args:
        if arg not in self.available_choices:
            raise ValueError(f"Invalid choice: {arg}. Must be one of {self.available_choices}")

def validate_min_max_args(args):
    """
    Check if value of arguments is between minimum and maximum values.
    :param args: The received arguments.
    """
    for arg in args:
        if arg < 0 or arg > 100:
            raise ValueError("Invalid argument value")
    return True

def get_nested_custom_and_control_args(args):
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg.startswith("nested_"):
            nested_args[arg] = args[arg]
        else:
            nested_args[arg] = args[arg]

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is not None:
        for var in extra_vars:
            vars_dict[var] = True

def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Convert arguments to correct types
    for key, value in values_dict.items():
        if key in ["--port", "-p"]:
            values_dict[key] = int(value)
        elif key in ["--host", "-h"]:
            values_dict[key] = str(value)
        elif key in ["--username", "-u"]:
            values_dict[key] = str(value)
        elif key in ["--password", "-p"]:
            values_dict[key] = str(value)
        elif key in ["--verbose", "-v"]:
            values_dict[key] = bool(value)
        else:
            values_dict[key] = str(value)

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = {}
    with open(plugin_dir + '/plugin.json') as f:
        plugin_spec = json.load(f)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[key + '.' + subkey] = subvalue
        else:
            flatten_dict[key] = value
    return flatten_dict

def inject_config(self):
    if "CONFIG_PATH" not in os.environ:
        os.environ["CONFIG_PATH"] = "/path/to/config"

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
